module Ops
  # The snapshot as Markdown, for reports/ops/ (generated by bin/rails ops:report, never edited).
  module Report
    module_function

    def markdown(s)
      c = s[:check_ins]
      lines = []
      lines << "# Operations: #{s[:clinic][:name]}"
      lines << ""
      lines << "Generated #{s[:generated_at]} by `bin/rails ops:report`, over the last #{s[:window][:days]} days. Do not edit by hand."
      lines << ""
      lines << "## Releases (reviews pooled over all clinics)"
      lines << ""
      lines << "| Workflow | Baseline → candidate | Reviews | Rejected | Rejected or edited | 95% interval of the change | Decision |"
      lines << "|---|---|---:|---:|---:|---|---|"
      s[:releases].each do |r|
        rej = r[:metrics]["rejected"] || {}
        chg = r[:metrics]["needed_changes"] || {}
        lines << "| #{r[:kind]} | #{r.dig(:baseline, :label) || '–'} → #{r.dig(:candidate, :label) || '–'} | " \
                 "#{r.dig(:baseline, :reviewed) || 0} / #{r.dig(:candidate, :reviewed) || 0} | #{pct(rej[:baseline])} → #{pct(rej[:candidate])} | " \
                 "#{pct(chg[:baseline])} → #{pct(chg[:candidate])} | #{interval(rej)}; #{interval(chg)} | **#{r[:decision]}** |"
      end
      lines << ""
      lines << "## Check-ins"
      lines << ""
      lines << "#{c[:met]} of #{c[:due]} due check-ins (#{pct(c[:share_met])}) were answered within #{c[:promise_hours]} h; " \
               "median #{c.dig(:hours_to_answer, :median) || '–'} h, slowest tenth #{c.dig(:hours_to_answer, :p90) || '–'} h. " \
               "#{c[:open]} open, #{c[:open_overdue]} past the promise."
      lines << ""
      lines << "## Model calls"
      lines << ""
      lines << "| Workflow | Prompt | Calls | Failed | p50 | p95 | Tokens in / out | Cost (placeholder rates) |"
      lines << "|---|---|---:|---:|---:|---:|---:|---:|"
      s[:models][:tasks].each do |t|
        lines << "| #{t[:task]} | #{t[:prompt_version] || '–'} | #{t[:calls]} | #{t[:errors] + t[:refused]} | #{ms(t.dig(:latency_ms, :p50))} | " \
                 "#{ms(t.dig(:latency_ms, :p95))} | #{'≈' if t[:tokens_estimated]}#{t[:input_tokens]} / #{t[:output_tokens]} | €#{format('%.4f', t[:cost_eur])} |"
      end
      lines << ""
      lines << "## Alerts"
      lines << ""
      lines.concat(s[:alerts].empty? ? [ "None." ] : s[:alerts].map { |a| "- **#{a[:level]}** #{a[:message]}" })
      lines.join("\n") + "\n"
    end

    def pct(x) = x.nil? ? "–" : format("%.1f%%", x * 100)
    def ms(x) = x.nil? ? "–" : format("%.1f s", x / 1000.0)
    def interval(m) = m[:low].nil? ? "–" : format("%+.1f to %+.1f pts", m[:low] * 100, m[:high] * 100)
  end
end
